import { type CSSProperties, type HTMLAttributes } from "react";
import { mergeClasses } from "./classes";
import { roundedClasses, type Rounded } from "./form";
import {
  BalsaThemeContext,
  useResolvedThemeProps,
} from "./theme-context";
import type { ThemeInput } from "./theme";
import type { SemanticColor } from "./types";

export type ProgressVariant = "solid" | "soft" | "striped";
export type ProgressSize = "sm" | "md" | "lg";
export type ProgressState = "loading" | "complete" | "indeterminate";

export interface ProgressProps extends HTMLAttributes<HTMLDivElement> {
  label: string;
  value?: number | null;
  max?: number;
  showValue?: boolean;
  formatValue?: (value: number, max: number) => string;
  indeterminateLabel?: string;
  variant?: ProgressVariant;
  color?: SemanticColor;
  size?: ProgressSize;
  rounded?: Rounded;
  theme?: ThemeInput;
}

const trackColorClasses: Readonly<Record<SemanticColor, string>> = {
  primary: "bg-balsa-primary/15",
  secondary: "bg-balsa-secondary/15",
  accent: "bg-balsa-accent/15",
  destructive: "bg-balsa-destructive/15",
  success: "bg-balsa-success/15",
  warning: "bg-balsa-warning/15",
  info: "bg-balsa-info/15",
};
const indicatorColorClasses: Readonly<Record<SemanticColor, string>> = {
  primary: "bg-balsa-primary",
  secondary: "bg-balsa-secondary",
  accent: "bg-balsa-accent",
  destructive: "bg-balsa-destructive",
  success: "bg-balsa-success",
  warning: "bg-balsa-warning",
  info: "bg-balsa-info",
};
const sizeClasses: Readonly<Record<ProgressSize, string>> = {
  sm: "h-1.5",
  md: "h-2.5",
  lg: "h-4",
};
const labelSizeClasses: Readonly<Record<ProgressSize, string>> = {
  sm: "text-xs",
  md: "text-sm",
  lg: "text-base",
};
const indicatorVariantClasses: Readonly<Record<ProgressVariant, string[]>> = {
  solid: [],
  soft: ["opacity-75"],
  striped: [],
};

export function Progress(rawProps: ProgressProps) {
  const { props, theme } = useResolvedThemeProps("progress", "controls", rawProps, {
    variant: "solid",
    size: "md",
    rounded: "full",
  } as const);
  const {
    label,
    value = null,
    max = 100,
    showValue = true,
    formatValue,
    indeterminateLabel = "In progress",
    variant,
    color = "info",
    size,
    rounded,
    theme: _themeInput,
    className,
    style,
    ...domProps
  } = props;
  void _themeInput;

  const safeMax = Number.isFinite(max) && max > 0 ? max : 100;
  const determinate = value !== null && Number.isFinite(value);
  const normalizedValue = determinate ? Math.min(safeMax, Math.max(0, Number(value))) : null;
  const percentage = normalizedValue === null ? 0 : (normalizedValue / safeMax) * 100;
  const state: ProgressState = !determinate
    ? "indeterminate"
    : percentage >= 100
      ? "complete"
      : "loading";
  const valueText = normalizedValue === null
    ? indeterminateLabel
    : formatValue
      ? formatValue(normalizedValue, safeMax)
      : `${Math.round(percentage)}%`;

  return (
    <BalsaThemeContext.Provider value={theme}>
      <div
        {...domProps}
        data-balsa="progress"
        data-theme={theme.explicitPresentation?.id}
        data-theme-base={theme.explicitPresentation?.base}
        data-state={state}
        data-variant={variant}
        data-color={color}
        data-size={size}
        data-rounded={rounded}
        className={mergeClasses("min-w-0 font-balsa-body", className)}
        style={
          {
            ...theme.explicitPresentation?.style,
            ...style,
          } as CSSProperties
        }
      >
        <div
          className={mergeClasses(
            "mb-balsa-xs flex min-w-0 items-baseline justify-between gap-balsa-lg",
            labelSizeClasses[size],
          )}
        >
          <span className="min-w-0 text-sm font-medium text-balsa-foreground">{label}</span>
          {showValue ? (
            <span className="shrink-0 tabular-nums text-balsa-muted-foreground" aria-hidden="true">
              {valueText}
            </span>
          ) : null}
        </div>
        <div
          data-balsa="progress-track"
          role="progressbar"
          aria-label={label}
          aria-valuemin={0}
          aria-valuemax={safeMax}
          aria-valuenow={normalizedValue ?? undefined}
          aria-valuetext={valueText}
          className={mergeClasses(
            "relative w-full overflow-hidden",
            sizeClasses[size],
            roundedClasses[rounded],
            trackColorClasses[color],
          )}
        >
          <div
            data-balsa="progress-indicator"
            data-state={state}
            data-variant={variant}
            style={{ width: state === "indeterminate" ? "40%" : `${percentage}%` }}
            className={mergeClasses(
              "relative h-full overflow-hidden transition-[width,transform] duration-balsa-slow ease-balsa motion-reduce:transition-none",
              roundedClasses[rounded],
              indicatorColorClasses[color],
              indicatorVariantClasses[variant],
            )}
          />
        </div>
      </div>
    </BalsaThemeContext.Provider>
  );
}

import { extendTailwindMerge, type ClassNameValue } from "tailwind-merge";

/**
 * Every custom scale has to be declared here, not only defined in CSS.
 *
 * tailwind-merge decides which of two classes wins by knowing they belong to
 * the same group. A scale it has not been told about is not a group, so a
 * component's own `gap-balsa-md` and a caller's `gap-3` both survive the merge
 * and whichever CSS rule happens to come last decides — the caller's override
 * silently stops working. That is what happened the moment the spacing scale
 * landed, and it is invisible in the source: the class list looks right.
 */
const twMerge = extendTailwindMerge({
  extend: {
    theme: {
      radius: ["balsa-control", "balsa-surface", "balsa-panel"],
      text: [
        "balsa-2xs",
        "balsa-xs",
        "balsa-sm",
        "balsa-base",
        "balsa-prose",
        "balsa-lg",
        "balsa-xl",
        "balsa-2xl",
        "balsa-3xl",
        "balsa-4xl",
        "balsa-5xl",
        "balsa-6xl",
      ],
      leading: ["balsa-tight", "balsa-snug", "balsa-normal", "balsa-relaxed", "balsa-prose"],
      tracking: ["balsa-title", "balsa-normal", "balsa-label"],
      shadow: [
        "balsa-control",
        "balsa-surface",
        "balsa-panel",
        "balsa-sm",
        "balsa-md",
        "balsa-lg",
        "balsa-detail",
      ],
      spacing: [
        "balsa-4xs",
        "balsa-3xs",
        "balsa-2xs",
        "balsa-xs",
        "balsa-sm",
        "balsa-md",
        "balsa-lg",
        "balsa-xl",
        "balsa-2xl",
        "balsa-3xl",
        "balsa-section-sm",
        "balsa-section-md",
        "balsa-section-lg",
        "balsa-control-inline",
        "balsa-density-compact",
        "balsa-density-default",
        "balsa-density-comfortable",
      ],
    },
    classGroups: {
      // `backdrop-balsa` is a custom utility rather than a value on a scale, so
      // it has to join the group it competes with by name. Without this a
      // caller's `backdrop-blur-none` and the component's `backdrop-balsa` both
      // survive the merge and CSS order decides which blur wins — the same
      // failure the spacing scale hit the moment it landed.
      "backdrop-blur": ["backdrop-balsa", "backdrop-balsa-overlay"],
    },
  },
});

export function mergeClasses(...inputs: unknown[]): string {
  return twMerge(...(inputs as ClassNameValue[]));
}

export function withoutClassAttribute(
  attrs: Readonly<Record<string, unknown>>,
): Record<string, unknown> {
  return Object.fromEntries(
    Object.entries(attrs).filter(([name]) => name !== "class"),
  );
}

import { CircleAlert, CircleCheckBig } from "lucide-react";
import type { IconComponent } from "./Icon";

export const fieldLabelClasses =
  "mb-balsa-2xs block text-sm font-medium leading-snug text-balsa-foreground";

export const fieldHintClasses = "mt-balsa-2xs block text-sm text-balsa-muted-foreground";

export const textControlClasses =
  "w-full rounded-lg border font-balsa-body text-balsa-input-foreground outline-none transition-[border-color,box-shadow,opacity] placeholder:text-balsa-muted-foreground focus:border-balsa-focus-ring focus:ring-2 focus:ring-balsa-focus-ring/30 disabled:border-balsa-border disabled:bg-balsa-disabled disabled:text-balsa-disabled-foreground";

export const textControlPopupClasses =
  "max-h-64 overflow-auto rounded-lg p-balsa-3xs text-balsa-surface-elevated-foreground shadow-balsa-surface transition-[opacity,transform,visibility] duration-balsa-fast ease-balsa";

export const textControlOptionClasses =
  "flex min-h-8 w-full items-center justify-between rounded-md px-balsa-sm py-balsa-2xs text-left text-sm transition-colors";

/*
 * No bare `border`. Tailwind compiles it to a literal 1px, which outranks the
 * `border-width: var(--balsa-border-width)` the stylesheet sets on these
 * controls -- so a checkbox and a radio kept a 1px edge at every border
 * setting while everything around them moved. The colour utilities stay; only
 * the width comes from the token.
 */
export const choiceInputClasses =
  "shrink-0 cursor-pointer appearance-none outline-none transition-[border-color,background-color,box-shadow,opacity] focus-visible:border-balsa-focus-ring focus-visible:ring-2 focus-visible:ring-balsa-focus-ring/30 disabled:cursor-not-allowed disabled:border-balsa-border disabled:bg-balsa-disabled";

export type FieldStatus = "default" | "validated" | "unvalidated";
export type FieldSize = "sm" | "md";
export type FieldVariant = "outline" | "surface" | "soft" | "glass";
export type Rounded = "none" | "sm" | "md" | "lg" | "xl" | "2xl" | "3xl" | "full";
export type TextareaResize = "none" | "vertical" | "both";

export const roundedClasses: Readonly<Record<Rounded, string>> = {
  none: "rounded-none",
  sm: "rounded-sm",
  md: "rounded-md",
  lg: "rounded-lg",
  xl: "rounded-xl",
  "2xl": "rounded-2xl",
  "3xl": "rounded-3xl",
  full: "rounded-full",
};

/**
 * A surface that may be contained by another one.
 *
 * `auto` means "concentric with whatever contains me": the corner follows the
 * containing surface's radius minus the inset between them, so the gap between
 * the two edges stays even instead of thickening at every corner. A surface
 * standing on its own finds nothing published to nest inside and keeps the
 * ordinary surface radius.
 *
 * Kept apart from `Rounded` because that union is shared with text controls,
 * where there is nothing to be concentric with and `auto` would be a value
 * nobody could act on.
 */
export type SurfaceRounded = Rounded | "auto";

export const surfaceRoundedClasses: Readonly<Record<SurfaceRounded, string>> = {
  ...roundedClasses,
  // Deliberately no class. The radius comes from the concentric rule in
  // balsa-theme.css, keyed on data-rounded="auto"; a utility emitted here would
  // outrank it and pin the corner to one value.
  auto: "",
};

const fieldVariantClasses: Readonly<Record<FieldVariant, string>> = {
  outline: "border-balsa-input-border bg-balsa-background",
  surface: "border-balsa-input-border bg-balsa-input",
  soft: "border-transparent bg-balsa-muted",
  glass: "border-balsa-border/70 bg-balsa-surface/70 backdrop-balsa",
};

const fieldPopupVariantClasses: Readonly<Record<FieldVariant, string>> = {
  outline: "border-balsa-input-border bg-balsa-background",
  surface: "border-balsa-border-strong bg-balsa-surface-elevated",
  soft: "border-transparent bg-balsa-muted",
  glass: "border-balsa-border/70 bg-balsa-surface/80 backdrop-balsa",
};

export interface AnchoredPopupPosition {
  left: number;
  top: number;
  width: number;
}

const textControlSizeClasses: Record<FieldSize, string[]> = {
  sm: ["h-8", "px-balsa-md", "text-sm"],
  md: ["h-9", "px-balsa-md", "text-sm"],
};

const textareaResizeClasses: Readonly<Record<TextareaResize, string>> = {
  none: "resize-none",
  vertical: "resize-y",
  both: "resize",
};

export const fieldStatusMessages: Record<
  Extract<FieldStatus, "unvalidated">,
  string
> = {
  unvalidated: "Check this information and try again.",
};

export function getTextControlClasses(
  status: FieldStatus,
  hasAdornment: boolean,
  disabled: boolean,
  loading: boolean,
  size: FieldSize = "md",
  rounded: Rounded = "lg",
  variant: FieldVariant = "surface",
): string[] {
  const resolvedSize = textControlSizeClasses[size] ? size : "md";
  return [
    textControlClasses,
    fieldVariantClasses[variant],
    roundedClasses[rounded],
    ...textControlSizeClasses[resolvedSize],
    ...(loading
      ? ["disabled:cursor-progress"]
      : disabled
        ? ["disabled:cursor-not-allowed"]
        : ["cursor-pointer"]),
    ...(status === "validated" ? ["border-balsa-success", "focus:border-balsa-success"] : []),
    ...(status === "unvalidated"
      ? ["border-balsa-destructive", "focus:border-balsa-destructive", "focus:ring-balsa-destructive/30"]
      : []),
    ...(hasAdornment ? ["pr-10"] : []),
  ];
}

export function getTextControlPopupClasses(
  rounded: Rounded = "lg",
  variant: FieldVariant = "surface",
): string[] {
  return [textControlPopupClasses, roundedClasses[rounded], fieldPopupVariantClasses[variant]];
}

export function getTextareaControlClasses(
  status: FieldStatus,
  disabled: boolean,
  loading: boolean,
  size: FieldSize = "md",
  rounded: Rounded = "lg",
  resizable: TextareaResize = "vertical",
  hasAdornment = false,
  variant: FieldVariant = "surface",
): string[] {
  return [
    textControlClasses,
    fieldVariantClasses[variant],
    "h-auto min-h-0 py-balsa-xs leading-6",
    roundedClasses[rounded],
    textareaResizeClasses[resizable],
    size === "sm" ? "px-balsa-md text-sm leading-5" : "px-balsa-md text-sm leading-6",
    ...(loading
      ? ["disabled:cursor-progress"]
      : disabled
        ? ["disabled:cursor-not-allowed"]
        : ["cursor-text"]),
    ...(status === "validated" ? ["border-balsa-success", "focus:border-balsa-success"] : []),
    ...(status === "unvalidated"
      ? ["border-balsa-destructive", "focus:border-balsa-destructive", "focus:ring-balsa-destructive/30"]
      : []),
    ...(hasAdornment ? ["pr-10"] : []),
  ];
}

export function getChoiceInputClasses(variant: FieldVariant = "surface"): string[] {
  return [choiceInputClasses, fieldVariantClasses[variant]];
}

export function getChoiceTrackClasses(variant: FieldVariant = "surface"): string {
  return fieldVariantClasses[variant];
}

export function getAnchoredPopupPosition(
  trigger: HTMLElement,
  popup: HTMLElement,
  fallbackHeight = 256,
): AnchoredPopupPosition {
  const triggerRect = trigger.getBoundingClientRect();
  const popupRect = popup.getBoundingClientRect();
  const viewportPadding = 8;
  const gap = 8;
  const width = Math.min(
    triggerRect.width,
    window.innerWidth - viewportPadding * 2,
  );
  const height = popupRect.height || fallbackHeight;
  const maxLeft = Math.max(
    viewportPadding,
    window.innerWidth - width - viewportPadding,
  );

  return {
    width,
    left: Math.min(Math.max(triggerRect.left, viewportPadding), maxLeft),
    top:
      triggerRect.bottom + gap + height <= window.innerHeight - viewportPadding
        ? triggerRect.bottom + gap
        : Math.max(viewportPadding, triggerRect.top - height - gap),
  };
}

export function getFieldStatusIcon(status: FieldStatus): IconComponent | undefined {
  if (status === "validated") return CircleCheckBig;
  if (status === "unvalidated") return CircleAlert;
  return undefined;
}

export function getFieldStateColorClass(status: FieldStatus): string {
  if (status === "unvalidated") return "text-balsa-destructive";
  if (status === "validated") return "text-balsa-success";
  return "text-balsa-muted-foreground";
}

export type ActionColor = "neutral" | "primary" | "secondary" | "accent" | "destructive";
export type StatusColor = "success" | "warning" | "info";
/**
 * Status surfaces communicate state, so they exclude neutral: an action can
 * legitimately carry no emphasis, but a status that means nothing is not a status.
 */
export type SemanticColor = Exclude<ActionColor, "neutral"> | StatusColor;
export type Rounded = "none" | "sm" | "md" | "lg" | "xl" | "2xl" | "3xl" | "full";
export type CardVariant = "surface" | "elevated" | "muted" | "outline" | "soft" | "glass";
export type CardColor = ActionColor;
export type CardPadding = "none" | "sm" | "md" | "lg";
export type CardSize = Exclude<CardPadding, "none">;

interface ActionColorClassSet {
  solid: string[];
  soft: string[];
  outline: string[];
  glass: string[];
  text: string[];
}

interface SemanticColorClassSet {
  solid: string[];
  soft: string[];
  outline: string[];
  glass: string[];
}

export const actionColorClasses: Readonly<Record<ActionColor, ActionColorClassSet>> = {
